sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiProperty = "singlescore"; // System property for inaccurate user records
    var totalUsers = 682; // Total user count in sys_user
    var totalInaccurateRecords = 0;

    function fetchKPI(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName); // Fetch system property

        if (propertyValue) {
            try {
                kpis = JSON.parse(propertyValue);
            } catch (e) {
                gs.info("Error parsing " + propertyName + ": " + e.message);
            }
        }
        return kpis;
    }

    function calculateTotalInaccurateRecords(kpis) {
        if (Array.isArray(kpis.output)) {
            kpis.output.forEach(function (kpi) {
                totalInaccurateRecords += kpi.count || 0;
            });
        }
    }

    var kpiData = fetchKPI(kpiProperty);
    calculateTotalInaccurateRecords(kpiData);

    var totalPercentage = ((totalInaccurateRecords / totalUsers) * 100).toFixed(2); // Calculate total percentage

    return {
        "singlecore_output": totalPercentage // Return as a single value
    };
}
